import{_ as o,o as a,c as t,N as r}from"./chunks/framework.11ad0a06.js";const h=JSON.parse('{"title":"Graceful Degradation","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/degrade.md","lastUpdated":1795525255000}'),i={name:"en/guide/degrade.md"};function d(n,e,s,c,l,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="graceful-degradation" tabindex="-1">Graceful Degradation <a class="header-anchor" href="#graceful-degradation" aria-label="Permalink to &quot;Graceful Degradation&quot;">​</a></h1><p>Wujie provides a transparent fallback mechanism for browsers that do not support modern APIs.</p><p>In standard mode, the sub-app&#39;s DOM lives inside a Web Component and its JavaScript runs inside an <code>iframe</code>, with <code>Proxy</code> bridging DOM operations from the <code>iframe</code> to the Web Component. Because legacy browsers such as IE do not support Web Components or <code>Proxy</code>, Wujie falls back to using a second <code>iframe</code> in place of the Web Component and <code>Object.defineProperty</code> in place of <code>Proxy</code>.</p><div class="warning custom-block"><p class="custom-block-title">Note</p><p>Wujie does not bundle ES6 polyfills because browser support targets vary by project. If you need to support older browsers, include the required polyfills via Babel in your own build setup.</p></div><h2 id="pros" tabindex="-1">Pros <a class="header-anchor" href="#pros" aria-label="Permalink to &quot;Pros&quot;">​</a></h2><ol><li><p>Automatic detection — Wujie automatically degrades when the browser lacks Web Components or <code>Proxy</code> support.</p></li><li><p>Strict application isolation is preserved even in Degrade Mode.</p></li><li><p>Zero code changes required — existing preloading, Keep-Alive mode, and communication code continue to work identically across standard and degraded environments.</p></li><li><p>Opt-in forced degradation — even on modern browsers, you can explicitly set <a href="/doc/en/api/startApp.html#degrade">degrade</a> to <code>true</code> if you prefer rendering the sub-app&#39;s DOM inside an <code>iframe</code>.</p></li></ol><h2 id="cons" tabindex="-1">Cons <a class="header-anchor" href="#cons" aria-label="Permalink to &quot;Cons&quot;">​</a></h2><ol><li><p>Modals and popups are constrained inside the sub-app&#39;s <code>iframe</code> and cannot cover the full viewport.</p></li><li><p>Without <code>Proxy</code>, Wujie cannot intercept <code>window.location</code>, so reading <code>window.location.host</code> returns the main app&#39;s host. Use <a href="/doc/en/api/wujie.html#wujie-location">$wujie.location</a> to retrieve the sub-app&#39;s actual host instead.</p></li></ol>',8)])])}const m=o(i,[["render",d]]);export{h as __pageData,m as default};
